from playwright.sync_api import sync_playwright
JS=r"""()=>{ const T=[]; const t=(n,ok,v)=>T.push((ok?'ok':'KO')+' · '+n+(ok?'':' '+JSON.stringify(v===undefined?'':v)));
window.CS_NOANIM=1; V.mp=null; V.univSel=['Le Seigneur des Anneaux']; startSolo(); const G=H.G; G.ps.forEach(q=>{ q.hero=q.hero||q.ho[0]; }); const p=G.ps[0], q=G.ps[1]; p.hero='lh_legolas'; finishHero(); clearInterval(H.tick);
const D=(a,h,f)=>{const m=fullM(mk('tl_snaga',0)); m.a=a; m.h=h; m.f=f||''; return m;};
const reset=(hero,...ids)=>{ p.hero=hero||'lh_legolas'; p.bd=ids.map(c=>typeof c==='string'?mk(c,0):c); p.hd=[]; p.g=10; p.pu=false; p.lg=0; p.et=0; p.vq=[]; p.disc=null; p.rh=0; p.sp=null; p.foe=null; p.vres=null; G.rd++; return p.bd; };
const run=(en,seed)=>{ const b=combatBoard(p); const e=en.map(x=>Object.assign({},x)); loNazgul(p,e); const r=simulate(b,e,seed||7,1,1,[0,0],G.mx); r.b=b; r.e=e; return r; };
const post=(r)=>{ const i=r.frames.findIndex(f=>f.at||f.gj); return r.frames[i<0?r.frames.length-1:Math.max(0,i-1)]; };
const ids=Object.keys(C).filter(c=>/^lo_/.test(c)), fam={}; ids.forEach(c=>{ fam[CD(c).tr]=(fam[CD(c).tr]||0)+1; });
t('50 cartes, 10 par famille', ids.length===50&&Object.values(fam).every(n=>n===10)&&Object.keys(fam).length===5, fam);
t('niveaux 1 à 6 dans chaque famille', LOV.every(tr=>[1,2,3,4,5,6].every(k=>ids.some(c=>CD(c).tr===tr&&CD(c).t===k))));
const hs=Object.keys(HEROES).filter(h=>/^lh_/.test(h)); t('20 héros, des deux camps', hs.length===20&&hs.filter(h=>HEROES[h].shadow).length===5, hs.length);
{ const bad=[]; Object.keys(C).filter(c=>/^(lo_|tl_)/.test(c)).forEach(c=>{ (CD(c).fxAll||[]).forEach(e=>{ let x=''; try{ x=ET[e.k]?ET[e.k].txt(e,1):'??'; }catch(er){ x='ERR'; } if(/\?\?|ERR|undefined|NaN|\bvous\b|votre/.test(x)) bad.push(c+':'+e.k+':'+x.slice(0,60)); }); }); Object.keys(SPELLS).filter(k=>SPELLS[k].lo).forEach(k=>{ const S=SPELLS[k]; if(!S.tx||/undefined|\bvous\b|votre/.test(S.tx+(S.stx||''))) bad.push(k); (S.sig||[]).forEach(c=>{ if(!C[c]) bad.push(k+' sig '+c); }); }); hs.forEach(h=>{ if(/\bvous\b|votre|undefined/.test(HEROES[h].tx)) bad.push(h); }); LO_ETAPES.forEach(e=>e.rw.forEach(id=>{ if(!SPELLS[id]) bad.push('rw '+id); })); LO_GROUPS.forEach(g=>g.m.forEach(c=>{ if(!C[c]) bad.push(g.id+' '+c); })); t('textes et références valides', !bad.length, bad.slice(0,6)); }
{ const nog=ids.filter(c=>!(NK_GOF[c]||[]).length).map(c=>CD(c).n); t('cartes sans groupe : au plus 4', nog.length<=4, nog); }
// ---- voyage ----
{ reset(null,'lo_garde'); p.vres='loss'; loMarch(G,p); t('défaite : pas de lieue', p.lg===0&&p.et===0); p.vres='win'; loMarch(G,p); t('victoire : +1 lieue, Fondcombe atteinte', p.lg===1&&p.et===1&&p.vq.length===1, [p.lg,p.et,p.vq]); loTurn(G,p); t('étape : choix parmi 3 objets de Fondcombe', p.disc&&p.disc.length===3&&p.disc.every(x=>LO_ETAPES[0].rw.includes(x.sp))&&new Set(p.disc.map(x=>x.sp)).size===3&&p.dsc==='Fondcombe', p.disc); const pick=p.disc[1].sp; OPS.pick(G,p,{i:1}); t('choisir : l\'objet arrive en main, le choix se ferme', !p.disc&&p.hd.length===1&&p.hd[0].sp===pick, p.hd); 
  p.lg=4; p.vres='win'; loMarch(G,p); t('5 lieues : la Moria (3) et la Lórien (5) franchies d\'un coup', p.et===3&&p.vq.length===2, [p.et,p.vq]); loTurn(G,p); const d1=p.disc&&p.dsc; OPS.pick(G,p,{i:0}); t('deux étapes : deux choix à la suite', d1==='La Moria'&&p.disc&&p.dsc==='La Lórien', [d1,p.dsc]); OPS.pick(G,p,{i:0}); t('puis plus rien', !p.disc); }
// ---- objets ----
{ const [f,s]=reset(null,'lo_frodon','lo_sam'); p.hd=[{sp:'lo_dard',u:UID++},{sp:'lo_dard',u:UID++}]; const a0=f.a,s0=s.a; OPS.cast(G,p,{i:0,tg:0}); OPS.cast(G,p,{i:0,tg:1}); t('Dard : +2/+1 à tous, Insensible seulement sur Frodon (porteur du film)', f.a===a0+2&&s.a===s0+2&&(f.x||[]).some(e=>e.k==='soc_i1')&&!(s.x||[]).some(e=>e.k==='soc_i1')&&p.hd.length===0, [f.a,s.a,f.x,s.x]); }
{ const [a]=reset(null,'lo_aragorn'); a.g=1; const a0=a.a; p.hd=[{sp:'lo_anduril',u:UID++}]; OPS.cast(G,p,{i:0,tg:0}); t('objet sur une carte dorée : bonus doublé', a.a===a0+8, a.a-a0); }
{ reset(null,'lo_garde'); p.hd=[{sp:'lo_aigles',u:UID++}]; OPS.cast(G,p,{i:0}); t('Les Aigles arrivent : 2 Aigles géants', p.bd.filter(m=>m.c==='tl_aigle').length===2, p.bd.map(m=>m.c)); }
// ---- transformations ----
{ const [g,a,s]=reset(null,'lo_gandalf','lo_aragorn','lo_gollum'); p.et=1; loTfAll(p); t('étape 1 : personne ne change', !g.tf&&!a.tf&&!s.tf); p.et=2; loTfAll(p); t('la Moria : Sméagol devient Gollum (Camouflage), Grands-Pas devient Aragorn', s.tf===1&&s.tfn==='Gollum'&&has(s,'c')&&a.tf===1&&a.tfn==='Aragorn'&&!g.tf, [s.tfn,a.tfn]); p.et=5; const ga=g.a; loTfAll(p); t('le Rohan : Gandalf le Blanc (+4/+4, Bouclier divin)', g.tf===1&&g.tfn==='Gandalf le Blanc'&&has(g,'s'), [g.tfn,g.f]); t('Roi Elessar réservé à la carte dorée', a.tf===1, a.tf); a.g=1; loTfAll(p); t('Aragorn doré au Gondor : Roi Elessar', a.tf===2&&a.tfn==='Roi Elessar', a.tfn); loTfAll(p); t('pas de double transformation', g.tf===1&&a.tf===2); const r=run([D(1,50)]); t('Gandalf le Blanc : un Aigle géant au combat ; Elessar : 2 soldats des Morts', post(r).s[0].some(x=>x.c==='tl_aigle')&&post(r).s[0].filter(x=>x.c==='tl_morts').length===2, post(r).s[0].map(x=>x.c)); }
// ---- l'Anneau ----
{ reset(null,'lo_garde'); G.ps.forEach(x=>{ x.sp=null; x.hd=x.hd.filter(y=>y.sp!=='lo_anneau'); x.bd.forEach(m=>delete m.ring); }); const rd0=G.rd; G.rd=2; let seen=0; for(let i=0;i<200;i++){ p.sp=null; loShelf(G,p); if(p.sp) seen++; } t('l\'Anneau n\'apparaît pas avant le tour 3', seen===0); G.rd=5; seen=0; for(let i=0;i<300;i++){ p.sp=null; loShelf(G,p); if(p.sp&&p.sp.sp==='lo_anneau') seen++; } t('ensuite il apparaît parfois à l\'étagère', seen>20&&seen<120, seen); p.sp={sp:'lo_anneau',u:UID++}; q.sp=null; loShelf(G,q); let s2=0; for(let i=0;i<100;i++){ q.sp=null; loShelf(G,q); if(q.sp) s2++; } t('un seul Anneau : pas chez un autre tant qu\'il est en vente', s2===0, s2);
  p.g=10; const ok=OPS.buysp(G,p,{}); t('acheter l\'Anneau : 3 or', ok&&p.g===7&&p.hd.some(x=>x.sp==='lo_anneau'), [ok,p.g]); for(let i=0;i<100;i++){ q.sp=null; loShelf(G,q); if(q.sp) s2++; } t('pas d\'autre Anneau tant qu\'un joueur le détient', s2===0&&loOwner(G)===p, s2);
  const [gd]=p.bd; OPS.cast(G,p,{i:p.hd.findIndex(x=>x.sp==='lo_anneau'),tg:0}); t('équiper : le serviteur devient porteur', gd.ring===1&&loBearer(p)===gd&&loHas(p)); const r=run([D(1,300)]); const me=r.b[0]; t('porteur invisible en combat', has(me,'c')&&!has(gd,'c')); const ia=r.frames.findIndex(f=>f.at===me.u); const aft=ia>=0&&r.frames[ia+1]&&r.frames[ia+1].s[0].find(x=>x.u===me.u); t('son Camouflage ne tombe pas quand il attaque', ia>=0&&(!aft||(aft.f||'').includes('c')), [ia,aft&&aft.f]); t('les Nazgûl traquent le détenteur : un Nazgûl en face', r.e.some(x=>x.c==='tl_nazgul'), r.e.map(x=>x.c));
  const a0=gd.a; p.rh=0; loTurn(G,p); t('chaque tour : +2/+2 au porteur, corruption +1', gd.a===a0+2&&gd.rc===1&&p.rh===1, [gd.a-a0,gd.rc]); const r2=run([D(1,300)]); const n1=r2.e.find(x=>x.c==='tl_nazgul'); p.rh=6; const r3=run([D(1,300)]); const n2=r3.e.find(x=>x.c==='tl_nazgul'); t('le Nazgûl grossit avec le temps, et ils viennent à deux dès le 4e tour', n1.a===5&&n2.a===20&&r2.e.filter(x=>x.c==='tl_nazgul').length===1&&r3.e.filter(x=>x.c==='tl_nazgul').length===2, [n1.a,n2.a]);
  for(let i=0;i<3;i++) loTurn(G,p); t('4 tours : il tient encore', p.bd.includes(gd)&&gd.rc===4, gd.rc); loTurn(G,p); t('5e tour : il succombe, l\'Anneau revient en main', !p.bd.includes(gd)&&p.hd.some(x=>x.sp==='lo_anneau')&&!loBearer(p)&&loHas(p), [p.bd.length,p.hd]); }
{ const [f]=reset(null,'lo_frodon'); p.hd=[{sp:'lo_anneau',u:UID++}]; OPS.cast(G,p,{i:0,tg:0}); for(let i=0;i<7;i++) loTurn(G,p); t('un Hobbit résiste 7 tours', p.bd.includes(f)&&f.rc===7); loTurn(G,p); t('puis succombe', !p.bd.includes(f)); }
{ const [f]=reset('lh_frodon','lo_frodon'); p.hd=[{sp:'lo_anneau',u:UID++}]; OPS.cast(G,p,{i:0,tg:0}); t('héros Frodon : 2 tours de plus (9 pour un Hobbit)', loLimit(p,f)===9, loLimit(p,f)); }
{ const [g]=reset('lh_sauron','lo_garde'); p.hd=[{sp:'lo_anneau',u:UID++}]; OPS.cast(G,p,{i:0,tg:0}); for(let i=0;i<12;i++) loTurn(G,p); const r=run([D(1,50)]); t('héros Sauron : pas de corruption, pas de Nazgûl', p.bd.includes(g)&&!r.e.some(x=>x.c==='tl_nazgul')); }
{ const [g]=reset(null,'lo_garde'); p.hd=[{sp:'lo_anneau',u:UID++}]; OPS.cast(G,p,{i:0,tg:0}); const g0=p.g; OPS.sell(G,p,{i:0}); t('vendre le porteur : l\'Anneau revient en main', p.hd.some(x=>x.sp==='lo_anneau')&&!p.bd.length&&p.g===g0+1); }
{ reset('lh_bilbon','lo_garde'); t('héros Bilbon : l\'Anneau ne coûte rien', spCost(p,SPELLS.lo_anneau)===0); p.hero='lh_legolas'; t('les autres : 3 or', spCost(p,SPELLS.lo_anneau)===3); }
{ reset('lh_gollum','lo_garde'); q.hd=[{sp:'lo_anneau',u:UID++}]; q.al=true; loSteal(G,p,q); t('héros Gollum : il vole l\'Anneau au joueur qu\'il bat', p.hd.some(x=>x.sp==='lo_anneau')&&!loHas(q)); p.hd=[]; q.hd=[{sp:'lo_anneau',u:UID++}]; p.hero='lh_legolas'; loSteal(G,p,q); t('les autres héros ne volent pas', !loHas(p)&&loHas(q)); q.hd=[]; }
{ reset('lh_frodon','lo_garde'); G.ps.forEach(x=>{ x.sp=null; x.hd=x.hd.filter(y=>y.sp!=='lo_anneau'); }); const rd=G.rd; G.rd=3; loTurn(G,p); t('héros Frodon : reçoit l\'Anneau au tour 3 si personne ne l\'a', p.hd.some(x=>x.sp==='lo_anneau'), p.hd); G.rd=rd; p.hd=[]; }
// ---- groupes ----
{ const [f,s]=reset(null,'lo_frodon','lo_sam'); nkGroupsEot(G,p); const b=combatBoard(p); t('Frodon et Sam : Frodon +0/+4 en combat seulement, Sam hérite', b[0].h===f.h+4&&(s.gx||[]).some(e=>e.k==='die_inherit'), [b[0].h,f.h,s.gx]); }
{ const E=reset(null,'lo_theoden','lo_eomer','lo_eowyn'); nkGroupsEot(G,p); const b=combatBoard(p); t('Maison d\'Eorl (3) : +2/+2 et première attaque double', b.every((c,i)=>c.a===E[i].a+2&&(c.x||[]).some(e=>e.k==='soc_first')), b.map(c=>c.a)); }
{ const Cc=reset(null,'lo_thorin','lo_balin','lo_dain','lo_bilbon'); nkGroupsEot(G,p); const b=combatBoard(p); t('Thorin et Compagnie (4) : +6/+6 et Réincarnation', b.every((c,i)=>c.a===Cc[i].a+6&&has(c,'r')), b.map(c=>[c.a,c.f])); }
{ reset(null,'lo_gothmog','lo_troll','lo_orque'); nkGroupsEot(G,p); const r=run([D(1,50)]); t('L\'armée du Mordor (3) : 2 Snagas rejoignent le combat', post(r).s[0].filter(x=>x.c==='tl_snaga').length===2, post(r).s[0].map(x=>x.c)); }
{ const [m,pi]=reset(null,'lo_merry','lo_pippin'); const a=m.a; nkGroupsEot(G,p); t('Merry et Pippin : +1/+1 à la fin du tour', m.a===a+1&&pi.a===2); }
// ---- pouvoirs de héros ----
{ const bad=[]; hs.filter(h=>HEROES[h].cost).forEach(h=>{ reset(h,'lo_garde','lo_eomer','lo_troll'); p.bd[1].a=9; try{ if(!OPS.pow(G,p)) bad.push(h+' refusé'); else if(p.g!==10-HEROES[h].cost) bad.push(h+' or '+p.g); run([D(2,60),D(3,60)]); }catch(e){ bad.push(h+' '+e); } }); t('les 15 pouvoirs actifs se lancent et se paient', !bad.length&&hs.filter(h=>HEROES[h].cost).length===15, [bad,hs.filter(h=>HEROES[h].cost).length]); }
return T}"""
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)[:300]))
    pg.goto('file:///home/claude/taverne.html'); pg.wait_for_timeout(1200)
    r=pg.evaluate(JS); ko=[x for x in r if x.startswith('KO')]
    print(len(r),'contrôles,',len(ko),'KO'); [print(x[:400]) for x in r if not x.startswith('ok')]; print('errs',errs[:3]); b.close()
